    [Theory]
    [MemberData(nameof(Mistakes))]
    public void ABestWrittenOverWithoutAskingIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The programs keeping the larger; and bests written over only when a test says the new value is better - directly, by a
    /// measure of both, by an else turned round, by one step on - Kadane's largest sum, a best for each row, where the largest
    /// is, the last of a sorted list, a chain of smallest and largest, a search started afresh each time round, and a name made
    /// new for each row.
    /// </summary>
    [Theory]
    [InlineData("ends.py", "def longest_increasing(items):\n    ends = [0] * (len(items) + 1)\n    longest = 0\n    for i in range(len(items)):\n        length = 0\n        for j in range(1, longest + 1):\n            if items[ends[j]] < items[i]:\n                length = j\n        if length == longest or items[i] < items[ends[length + 1]]:\n            ends[length + 1] = i\n            longest = max(longest, length + 1)\n    return longest\n\n\nprint(longest_increasing([4, 1, 5, 3, 7, 6, 2]))\n")]
    [InlineData("lis.c", "#include <stdio.h>\n\nint lis(const int *items, int count) {\n    int ends[16] = {0};\n    int longest = 0;\n    for (int i = 0; i < count; i++) {\n        int length = 0;\n        for (int j = 1; j <= longest; j++) {\n            if (items[ends[j]] < items[i]) length = j;\n        }\n        if (length == longest || items[i] < items[ends[length + 1]]) {\n            ends[length + 1] = i;\n            longest = length + 1 > longest ? length + 1 : longest;\n        }\n    }\n    return longest;\n}\n\nint main(void) {\n    int items[] = {4, 1, 5, 3, 7, 6, 2};\n    printf(\"%d\\n\", lis(items, 7));\n    return 0;\n}\n")]
    [InlineData("lis.cpp", "#include <algorithm>\n#include <iostream>\n#include <vector>\n\nint lis(const std::vector<int>& items) {\n    std::vector<int> ends(items.size() + 1, 0);\n    int longest = 0;\n    for (int i = 0; i < static_cast<int>(items.size()); i++) {\n        int length = 0;\n        for (int j = 1; j <= longest; j++) {\n            if (items[ends[j]] < items[i]) {\n                length = j;\n            }\n        }\n        if (length == longest || items[i] < items[ends[length + 1]]) {\n            ends[length + 1] = i;\n            longest = std::max(longest, length + 1);\n        }\n    }\n    return longest;\n}\n\nint main() {\n    std::cout << lis({4, 1, 5, 3, 7, 6, 2}) << std::endl;\n    return 0;\n}\n")]
